package com.ivonix.pulse.ontology.global;
import com.ibm.icu.text.MessageFormat; import com.ibm.icu.util.ULocale; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class GlobalService{private final JdbcTemplate jdbc;public GlobalService(JdbcTemplate j){jdbc=j;}public Map<String,String> translations(String locale,String namespace){String normalized=locale.trim().toLowerCase(Locale.ROOT);List<String> chain=new ArrayList<>();String cur=normalized;for(int i=0;i<10&&cur!=null&&!chain.contains(cur);i++){chain.add(cur);cur=jdbc.query("select fallback from public.i18n_locales where code=? and enabled=true",rs->rs.next()?rs.getString(1):null,cur);}if(!chain.contains("en"))chain.add("en");Map<String,String> out=new LinkedHashMap<>();for(int i=chain.size()-1;i>=0;i--)for(Map<String,Object> r:jdbc.queryForList("select key,value from public.i18n_translations where locale=? and namespace=?",chain.get(i),namespace))out.put((String)r.get("key"),(String)r.get("value"));return out;}public String format(String locale,String template,Map<String,Object> vars){try{return new MessageFormat(template,new ULocale(locale)).format(vars);}catch(Exception e){throw new IllegalArgumentException("Invalid ICU message",e);}}@Transactional public void upsert(String locale,String namespace,String key,String value,UUID user){if(locale==null||namespace==null||key==null||value==null||namespace.length()>100||key.length()>200||value.length()>10000)throw new IllegalArgumentException("Invalid translation");Integer ok=jdbc.queryForObject("select count(*) from public.i18n_locales where code=? and enabled=true",Integer.class,locale);if(ok==null||ok!=1)throw new IllegalArgumentException("Locale disabled or unknown");jdbc.update("insert into public.i18n_translations(locale,namespace,key,value,updated_by) values(?,?,?,?,?) on conflict(locale,namespace,key) do update set value=excluded.value,updated_at=now(),updated_by=excluded.updated_by",locale,namespace,key,value,user);}public void pref(UUID user,String locale,String tz){Integer ok=jdbc.queryForObject("select count(*) from public.i18n_locales where code=? and enabled=true",Integer.class,locale);if(ok==null||ok!=1)throw new IllegalArgumentException("Locale disabled or unknown");if(tz!=null&&tz.length()>100)throw new IllegalArgumentException("Invalid timezone");jdbc.update("insert into public.i18n_user_prefs(user_id,locale,timezone) values(?,?,?) on conflict(user_id) do update set locale=excluded.locale,timezone=excluded.timezone,updated_at=now()",user,locale,tz);}public Map<String,Object> direction(String locale){return jdbc.queryForMap("select code,name,native_name,direction from public.i18n_locales where code=? and enabled=true",locale);}}
